/**
 * The composition root.
 *
 * One object, assembled once, injected through a React context. Components ask
 * the context for what they need and never import a repository directly — which
 * is what lets a test render a page with three fake methods and no network.
 *
 * The two `local*` entries are the placeholders for endpoints that do not exist
 * yet. Replacing either is a one-line change here.
 */

import type { Repositories } from '@/application/ports'
import { authRepository } from './api/auth'
import { bookingRepository } from './api/bookings'
import { catalogRepository } from './api/catalog'
import { paymentRepository } from './api/payments'
import { localReviewRepository } from './api/reviews'
import { localWishlistRepository } from './api/wishlist'

export const repositories: Repositories = {
  catalog: catalogRepository,
  bookings: bookingRepository,
  payments: paymentRepository,
  auth: authRepository,
  reviews: localReviewRepository, // ← swap when the reviews module ships
  wishlist: localWishlistRepository, // ← swap when the wishlist endpoint ships
}
