/**
 * `ReviewRepository` — **not yet backed by an API.**
 *
 * The backend has no reviews module; it lands in a later phase. Two things are
 * true at once and both matter:
 *
 * * Ratings shown on search cards and property pages are **real**. They come
 *   from `review_average` / `review_count`, which the property module already
 *   maintains, and they are read through the catalogue, not through here.
 * * Individual review *text* has no source. Reads return empty and writes are
 *   kept on the device, so a guest who writes one sees it and nobody else does.
 *
 * A stub that invented plausible-looking reviews would be far worse than an
 * empty state: fabricated reviews on a booking site are indistinguishable from
 * fraud, and someone would eventually ship them. So the empty state is honest
 * and the UI says the feature is coming.
 *
 * Swapping this for HTTP is one file plus one line in `repositories.ts`; the
 * port is already the shape the API will have.
 */

/* eslint-disable @typescript-eslint/require-await -- These methods are `async`
   because they implement an async port, not because they await anything today.
   Dropping `async` would make the signatures diverge from the interface the
   HTTP implementation will satisfy, which is the churn the port exists to
   prevent. */

import type { Page, ReviewRepository } from '@/application/ports'
import type { Review, ReviewSummary } from '@/domain/review'
import { summarise } from '@/domain/review'
import { readJson, writeJson } from '@/infrastructure/storage/localStore'

const KEY = 'draft-reviews'

function stored(): Review[] {
  return readJson<Review[]>(KEY, [])
}

export const localReviewRepository: ReviewRepository = {
  async forProperty(propertyId): Promise<Page<Review> & { summary: ReviewSummary }> {
    const mine = stored().filter((r) => r.propertyId === propertyId)
    return { items: mine, nextCursor: null, summary: summarise(mine) }
  },

  async mine() {
    return stored()
  },

  async submit(draft) {
    const review: Review = {
      id: crypto.randomUUID(),
      propertyId: draft.propertyId,
      bookingId: draft.bookingId,
      authorName: 'You',
      authorAvatarUrl: null,
      rating: draft.rating,
      title: draft.title || null,
      body: draft.body,
      stayedOn: null,
      createdAt: new Date().toISOString(),
      categories: draft.categories,
      hostReply: null,
    }
    writeJson(KEY, [review, ...stored().filter((r) => r.bookingId !== draft.bookingId)])
    return review
  },

  async remove(reviewId) {
    writeJson(
      KEY,
      stored().filter((r) => r.id !== reviewId),
    )
  },
}

/** Read by the UI so it can say so, instead of showing a silent empty list. */
export const REVIEWS_ARE_LOCAL_ONLY = true
