/**
 * `WishlistRepository`, on this device.
 *
 * **There is no wishlist endpoint yet.** This stores saved stays in
 * `localStorage`, which means they do not follow the guest to another device
 * and are lost if site data is cleared. That is a real limitation and it is
 * surfaced in the UI rather than hidden — the Wishlist page says so.
 *
 * When the endpoint lands, replace this object with an HTTP implementation and
 * change the one line in `infrastructure/repositories.ts`. Nothing above the
 * port changes, because the port was written for the eventual API rather than
 * for `localStorage`: every method is async, and `add` takes a whole entry so
 * the server can store a snapshot exactly as this does.
 */

/* eslint-disable @typescript-eslint/require-await -- These methods are `async`
   because they implement an async port, not because they await anything today.
   Dropping `async` would make the signatures diverge from the interface the
   HTTP implementation will satisfy, which is the churn the port exists to
   prevent. */

import type { WishlistRepository } from '@/application/ports'
import type { WishlistEntry } from '@/domain/wishlist'
import { readJson, removeItem, writeJson } from '@/infrastructure/storage/localStore'

const KEY = 'wishlist'

export const localWishlistRepository: WishlistRepository = {
  async list() {
    return readJson<WishlistEntry[]>(KEY, [])
  },

  async add(entry) {
    const current = readJson<WishlistEntry[]>(KEY, [])
    // Re-saving updates the snapshot rather than duplicating: a price that
    // moved since the guest saved it should be the price they see.
    const next = [entry, ...current.filter((e) => e.propertyId !== entry.propertyId)]
    writeJson(KEY, next)
  },

  async remove(propertyId) {
    writeJson(
      KEY,
      readJson<WishlistEntry[]>(KEY, []).filter((e) => e.propertyId !== propertyId),
    )
  },

  async clear() {
    removeItem(KEY)
  },
}
