/**
 * The wishlist.
 *
 * **No backend endpoint exists yet.** Saved stays live in this device's
 * `localStorage` behind `WishlistRepository`, which is a deliberate, temporary
 * choice with two consequences worth being honest about: the list does not
 * follow the guest to another device, and clearing site data loses it.
 *
 * It is still worth shipping. A wishlist is how people plan a trip over days,
 * and the alternative — no wishlist until a later phase — is worse than one
 * that is device-local. When the endpoint lands, only the repository changes;
 * the entry stores everything needed to render a card without a network call,
 * so a saved property renders offline and survives the property being delisted.
 */

export interface WishlistEntry {
  readonly propertyId: string
  readonly slug: string
  readonly name: string
  readonly city: string
  readonly coverImageUrl: string | null
  readonly fromPriceMinor: number | null
  readonly currency: string
  readonly reviewAverage: number
  readonly reviewCount: number
  readonly savedAt: string
  readonly note: string | null
}

export function isSaved(entries: readonly WishlistEntry[], propertyId: string): boolean {
  return entries.some((e) => e.propertyId === propertyId)
}

/** Newest first: the thing you just saved is the thing you want to see. */
export function sortByRecent(entries: readonly WishlistEntry[]): WishlistEntry[] {
  return [...entries].sort((a, b) => b.savedAt.localeCompare(a.savedAt))
}
